            self.migrate_individuals()
        self.phase_transition_adaptive_mapping()
        if self.eval_count >= self.budget * 0.8:
            self.initialize_population(bounds)

    def intensify_local_search(self, func, bounds):
        if self.eval_count % (self.migration_interval * 3) == 0:
            best_island_idx, best_ind_idx = np.unravel_index(np.argmin(self.fitness, axis=None), self.fitness.shape)
            best_individual = self.population[best_island_idx, best_ind_idx]
            for _ in range(int(self.local_search_intensity * self.population_size)):
                if self.eval_count >= self.budget:
                    break
                perturbation = np.random.normal(0, 0.1, self.dim)
                candidate = np.clip(best_individual + perturbation, bounds.lb, bounds.ub)
                candidate_fitness = func(candidate)
                self.eval_count += 1
